# --- management cluster (the same block in every op; generated by gen.py) ---
# Where this cluster's CAPI objects live — params.management:
#   hyve (default) — the cluster named by the template/cluster's
#     spec.mgmtCluster, whose kubeconfig hyve passes as HYVE_MGMT_KUBECONFIG
#   kubeconfig — a kubeconfig file at params.mgmt_kubeconfig (pipelines with
#     an existing management cluster outside hyve)
#   kind — a kind cluster on this machine (params.kind_cluster, default
#     hyve-capi), created and initialized by create. Local mode only.
name="$HYVE_CLUSTER_NAME"
ns="${HYVE_PARAM_NAMESPACE:-capi-clusters}"
management="${HYVE_PARAM_MANAGEMENT:-hyve}"
kind_name="${HYVE_PARAM_KIND_CLUSTER:-hyve-capi}"
cluster_res=clusters.v1beta2.cluster.x-k8s.io
mgmt_kc=""
mgmt_missing=false
case "$management" in
  hyve)
    if [ -z "$HYVE_MGMT_KUBECONFIG" ]; then
      echo "Error: no management cluster — set spec.mgmtCluster on the template or cluster (or params.management: kubeconfig or kind)" >&2
      exit 1
    fi
    mgmt_kc="$HYVE_MGMT_KUBECONFIG" ;;
  kubeconfig)
    mgmt_kc="$HYVE_PARAM_MGMT_KUBECONFIG"
    if [ -z "$mgmt_kc" ] || [ ! -r "$mgmt_kc" ]; then
      echo "Error: management: kubeconfig needs params.mgmt_kubeconfig to name a readable kubeconfig file (got '$mgmt_kc')" >&2
      exit 1
    fi ;;
  kind)
    for tool in kind docker; do
      if ! command -v "$tool" >/dev/null 2>&1; then
        echo "Error: management: kind needs $tool on PATH — it runs a kind cluster with Docker on this machine, so it's local mode only" >&2
        exit 1
      fi
    done
    if kind get clusters 2>/dev/null | grep -qx "$kind_name"; then
      mgmt_kc=$(mktemp)
      kind get kubeconfig --name "$kind_name" > "$mgmt_kc"
    else
      mgmt_missing=true
    fi ;;
  *)
    echo "Error: params.management must be hyve, kubeconfig, or kind (got '$management')" >&2
    exit 1 ;;
esac
mk() { kubectl --kubeconfig "$mgmt_kc" -n "$ns" "$@"; }
# --- end management cluster ---
